mapper.sql:
WITH src AS ( SELECT gid AS id, 'colonias' AS tabla, 'Colonia' AS tipo, 3 AS prio, COALESCE(localidad || ', ', '') || nom_asen AS busqueda, COALESCE(cp, '') AS extra, the_geom FROM ovie_web.colonias UNION ALL SELECT gid, 'localidades_busqueda', tipo, CASE tipo WHEN 'Municipio' THEN 1 ELSE 2 END, CASE tipo WHEN 'Municipio' THEN 'Nayarit, ' || nombre ELSE nom_mun || ', ' || nombre END, '', the_geom FROM ovie_web.localidades_busqueda ), m AS ( SELECT * FROM src WHERE 1 = 1
AND translate(lower(busqueda || ' ' || tipo || ' ' || extra), 'áéíóúüñàèìòù', 'aeiouunaeiou') LIKE '%' || #{token} || '%'
AND tipo = #{tipo}
)
